const d=plan.document('logo','fold.motion.document','GHATA · Golden Cell Loop');
const glyphs=[
 {key:'glyph',fill:'0ae0a144-2f67-46af-b10e-4a92c56c6ed0',xform:'ea1659e3-f008-40f9-bce3-0e34704853b1',grid:'6a11ee0b-c55d-402d-ab59-fd21224cbb8a',char:'G'},
 {key:'h_layer',fill:'165219bd-af89-4ea5-8d19-fa42fa55d491',xform:'38fc74d6-c5ca-408a-a7e2-3cf626f1bb27',char:'H'},
 {key:'a_intro',fill:'b9d2a09c-7677-44d0-912c-88857683b834',xform:'3da07e41-d893-4bc8-813d-9a98448371dd',char:'A'},
 {key:'t_layer',fill:'5a19b76c-6e33-4695-af35-41a275ed5e69',xform:'ee6f0f78-41d7-47b2-99cd-c28206c4ac67',char:'T'},
 {key:'a_loop',fill:'8283fe43-5d0e-4359-a1e6-f9bc04cf52d0',xform:'ff2da1a9-2781-42d2-a8ac-350017fadc28',char:'A'}
];
const pitch=d.control('cell_pitch','Cell spacing · px',30);
const diameter=d.control('cell_diameter','Cell diameter · pitch factor',0.88);
const gold=d.control('gold_tint','Palette · warm gold', [0.88,0.66,0.30,1]);
const speed=d.control('sequence_speed','Sequence speed · factor',1);
const time=d.node('clock','fold.motion.time');
const scaled=d.node('scaled_time','fold.motion.math',{settings:{operation:'Multiply',value_type:'Scalar'}}).connect('a',time).connect('b',speed);
const loop=d.node('loop_time','fold.motion.math',{settings:{operation:'Modulo',value_type:'Scalar'}}).set('b',3.6666667).connect('a',scaled);
function envelope(name,start,end,fallStart,fallEnd) {
 const rise=d.node(name+'_rise','fold.motion.map_range').set('source_min',start).set('source_max',end).set('target_min',0).set('target_max',1).set('smooth',true).connect('value',loop);
 const fall=d.node(name+'_fall','fold.motion.map_range').set('source_min',fallStart).set('source_max',fallEnd).set('target_min',1).set('target_max',0).set('smooth',true).connect('value',loop);
 return d.node(name+'_active','fold.motion.math',{settings:{operation:'Min',value_type:'Scalar'}}).connect('a',rise).connect('b',fall);
}
const gateG=envelope('gate_g',0,0.02,0.40,0.58);
const gateH=envelope('gate_h',0.40,0.58,1.08,1.25);
const gateA1=envelope('gate_a1',1.08,1.25,1.92,2.17);
const gateT=envelope('gate_t',1.92,2.17,2.58,2.75);
const gateA2=envelope('gate_a2',2.58,2.83,3.25,3.58);
for(const item of glyphs){
 d.existingNode(item.fill).connect('color',gold);
 d.existingNode(item.xform).set('translation',item.char==='G'?[335,-52]:[540,-52]);
 let grid;
 if(item.grid) grid=d.existingNode(item.grid).connect('cell_size',pitch).connect('cell_scale',diameter);
 else {
   grid=d.node('dots_'+item.key,'fold.motion.shape_grid').set('circular',true).connect('cell_size',pitch).connect('cell_scale',diameter);
   d.edit({op:'insert',node:item.xform,input:'content',modifier:grid.id,modifier_input:'content',output:'content'});
 }
 let gate=item.key==='glyph'?gateG:item.key==='h_layer'?gateH:item.key==='a_intro'?gateA1:item.key==='t_layer'?gateT:gateA2;
 const opacity=d.node('opacity_'+item.key,'fold.motion.set_opacity',{settings:{domain:'Children',combine:'Replace'}}).connect('value',gate);
 d.edit({op:'insert',node:item.xform,input:'content',modifier:opacity.id,modifier_input:'content',output:'content'});
}
